const VIEW_BOXES: Partial<Record<MeetupScribbleRawName, string>> = {
  hybrid_event_icon_filled: '0 0 24 24',
  two_chat_bubbles: '0 0 33 32',
}

export function MeetupScribble({
  name,
  size = 32,
  color,
  style,
}: {
  name: MeetupScribbleName
  size?: number
  color?: string
  style?: StyleProp<ViewStyle>
}) {
  const t = useTheme()
  const activeColor = color ?? t.text
  const raw: MeetupScribbleRawName = ALIASES[name] ?? (name as MeetupScribbleRawName)
  const vb = VIEW_BOXES[raw] ?? '0 0 32 32'

  return (
    <View style={[{ width: size, height: size, alignItems: 'center', justifyContent: 'center' }, style]}>
      <Svg width={size} height={size} viewBox={vb} fill="none">
        {renderScribbleGlyph(raw, activeColor)}
      </Svg>
    </View>
  )
}

/**
 * Nút vẽ tay tương tác (Meetup Scribble Interactive Button):
 * - Bật nảy đàn hồi (Spring scale 0.88 -> 1)
 * - Lắc nhẹ góc nghiêng (-14° -> 0°)
 * - Vòng sóng lan toả (Shockwave ripple)
 * - Rung xúc giác nhẹ (Haptics)
 */
export function ScribbleButton({
  name,
  label,
  size = 28,
  color,
  active = false,
  badge,
  onPress,
  style,
}: {
  name: MeetupScribbleName
  label: string
  size?: number
  color?: string
  active?: boolean
  badge?: number | string
  onPress: () => void
  style?: StyleProp<ViewStyle>
}) {
  const t = useTheme()
  const scale = useRef(new Animated.Value(1)).current
  const rot = useRef(new Animated.Value(0)).current
  const ripple = useRef(new Animated.Value(0)).current
  const [rippling, setRippling] = useState(false)

  const activeColor = color ?? (active ? t.primary : t.text)

  const handlePressIn = () => {
    Animated.spring(scale, {
      toValue: 0.86,
      speed: 45,
      bounciness: 5,
      useNativeDriver: true,
    }).start()
  }

  const handlePressOut = () => {
    Animated.spring(scale, {
      toValue: 1,
      friction: 3.8,
      tension: 200,
      useNativeDriver: true,
    }).start()
  }

  const handlePress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {})
    rot.setValue(-1)
    Animated.spring(rot, {
      toValue: 0,
      friction: 3.5,
      tension: 200,
      useNativeDriver: true,
    }).start()

    setRippling(true)
    ripple.setValue(0)
    Animated.timing(ripple, {
      toValue: 1,
      duration: 420,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start(({ finished }) => {
      if (finished) setRippling(false)
    })

    onPress()
  }

  const rotate = rot.interpolate({
    inputRange: [-1, 0, 1],
    outputRange: ['-14deg', '0deg', '14deg'],
  })
  const rippleScale = ripple.interpolate({
    inputRange: [0, 1],
    outputRange: [0.5, 1.85],
  })
  const rippleOpacity = ripple.interpolate({
    inputRange: [0, 0.3, 1],
    outputRange: [0.65, 0.4, 0],
  })

  return (
    <Pressable
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      accessibilityRole="button"
      accessibilityLabel={label}
      style={({ pressed }) => [
        {
          minWidth: size + 16,
          height: size + 16,
          borderRadius: (size + 16) / 2,
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: active ? t.primaryTint : pressed ? t.inputBg : 'transparent',
        },
        style,
      ]}
    >
      {rippling && (
        <Animated.View
          pointerEvents="none"
          style={{
            position: 'absolute',
            width: size + 6,
            height: size + 6,
            borderRadius: (size + 6) / 2,
            borderWidth: 1.8,
            borderColor: activeColor,
            opacity: rippleOpacity,
            transform: [{ scale: rippleScale }],
          }}
        />
      )}
      <Animated.View style={{ transform: [{ scale }, { rotate }], alignItems: 'center', justifyContent: 'center' }}>
        <MeetupScribble name={name} size={size} color={activeColor} />
        {badge != null && String(badge) !== '0' && (
          <View
            style={{
              position: 'absolute',
              top: -3,
              right: -5,
              minWidth: 14,
              height: 14,
              borderRadius: 7,
              backgroundColor: '#FF3040',
              borderWidth: 1.8,
              borderColor: t.card,
              alignItems: 'center',
              justifyContent: 'center',
              paddingHorizontal: 2,
            }}
          />
        )}
      </Animated.View>
    </Pressable>
  )
}
